fruits.shift();          // удалить первый
fruits.includes("банан");// есть ли элемент`},{h:`Методы перебора`},{table:{head:[`Метод`,`Что возвращает`],rows:[["`forEach`",`Ничего — просто перебирает`],["`map`",`Новый массив той же длины`],["`filter`",`Новый массив из подошедших элементов`],["`find`",`Первый подошедший элемент`],["`reduce`",`Одно значение — сумму, максимум, объект`],["`sort`",`Тот же массив, отсортированный`]]}},{code:`const prices = [100, 250, 80];

